import{_ as r,c as l,o as t,ag as e}from"./chunks/framework.Bkod66qp.js";const b=JSON.parse('{"title":"예술창작공간 대관규정","description":"","frontmatter":{"title":"예술창작공간 대관규정","subtitle":"","doc_id":"","last_update":"2018-03-23","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/802_예술창작공간 대관규정(180323).md","filePath":"regulation/802_예술창작공간 대관규정(180323).md"}'),o={name:"regulation/802_예술창작공간 대관규정(180323).md"};function s(n,a,i,c,d,h){return t(),l("div",null,a[0]||(a[0]=[e(`<h1 id="law-title" class="center" tabindex="-1">예술창작공간 대관규정 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;예술창작공간 대관규정 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2009.   3.   3
개정 2009.   9.   8
개정 2010.   3.  30
개정 2010.  10.  26
개정 2011.   3.  30
개정 2013.   6.  26
개정 2018.   3.  23</pre></div><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 규정은 재단법인 서울문화재단(이하 ‘재단’이라고 한다)이 운영하는 예술창작공간의 대관운영에 관한 제반 사항을 규정함을 목적으로 한다.</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (용어의 정의) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (용어의 정의) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(용어의 정의)</strong> ① ‘예술창작공간’(이하 ‘창작공간’이라 한다)이라 함은 예술가들의 창작활동을 지원하거나 시민을 위한 문화예술 프로그램 운영을 위해 조성된 공간을 말한다.<br> ② ‘대관’이라 함은 연습, 전시, 세미나 등 문화예술관련 행사 및 창작활동를 위하여 시설, 설비 및 부수장비를 소정의 절차를 거쳐 일정기간 동안 대관자에게 사용을 허가하는 것을 말한다.<br> ③ ‘대관자’라 함은 이 규정을 인정하고 재단의 대관승인을 받아 재단과 계약을 체결한 자를 말한다.<br> ④ ‘입주대관’이라 함은 창작공간 시설 중 창작자를 위한 상주형 전용 공간에 대해 재단이 별도로 정하는 조건에 맞추어 장기간 입주하여 사용하는 방식의 대관절차를 말한다.<br> ⑤ ‘기획대관’이라 함은 재단이 제시한 창작공간별 프로그램 운영계획에 부합하는 행사계획을 대관자가 제안하고 이를 재단이 공동으로 시행하고자 별도조건을 정하여 공간을 사용하는 방식의 대관절차를 말한다.<br> ⑥ ‘일반대관’이라 함은 대관이 가능한 일정에 대해 개별적으로 신청을 받아 사용하는 방식의 대관절차를 말한다. 일반대관은 재단이 별도로 정하는 기간 동안 일괄 대관신청을 받는 ‘정기대관’과 정기대관 심사를 마친 후 대관 가능한 잔여일정에 대해 개별적으로 대관신청을 받는 ‘수시대관’ 방식으로 나뉘어 시행한다.</p><h2 id="article3" class="sr-only" tabindex="-1">제3조 (대관의 범위) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (대관의 범위) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(대관의 범위)</strong> ① 삭제 &lt;2010. 10. 26.&gt;<br> ② 창작공간별 대관시설과 범위에 대한 세부 사항은 개별 창작공간의 운영에 대한 별도의 내규로 정한다.</p><h2 id="article4" class="sr-only" tabindex="-1">제4조 (사용료) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (사용료) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(사용료)</strong> ① 재단은 수익자 비용부담의 원칙을 적용하여 대관자에게 사용료를 징수할 수 있다.<br> ② 창작공간별 사용료는 시설유지비, 감가상각비, 인건비 등 원가요인과 창작공간별 운영의 목적을 고려하여 대표이사가 정한다.<br> ③ 창작공간별 사용료는 서울시창작공간 운영내규 서울시창작공간 시설별 사용료에 따른다. &lt;개정 2010. 10. 26.&gt;<br> ④ 대관자는 재단이 정한 계좌로 정한 기일까지 대관료를 일시불로 납부해야 한다. 단, 대관기간 중 추가로 부대설비 사용이 필요한 경우는 재단의 사용허가를 득하고, 대금을 납부한 후 사용할 수 있다.</p><h2 id="article5" class="sr-only" tabindex="-1">제5조 (사용료 면제 및 감면) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (사용료 면제 및 감면) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(사용료 면제 및 감면)</strong> 다음 경우에 한해 재단의 승인을 받은 경우 사용료를 면제 또는 감면할 수 있다. &lt;개정 2013. 6. 26.&gt;<br> ① 재단 사업 수행을 위해 사용하는 경우 &lt;개정 2013. 6. 26.&gt;<br> ② 공동 주최, 기획, 초청, 후원 등에 사용하는 경우 &lt;개정 2013. 6. 26.&gt;<br> ③ 공공 또는 공익상 특별한 사유가 있다고 인정되는 경우 &lt;개정 2013. 6. 26.&gt;<br> ④ 공간에 대한 취재 및 홍보를 목적으로 사용하는 경우 &lt;개정 2013. 6. 26.&gt;<br> ⑤ 기타 창작공간의 운영 목적을 달성하기 위해 필요하다고 판단되는 경우 &lt;개정 2013. 6. 26.&gt;</p><h2 id="article6" class="sr-only" tabindex="-1">제6조 (대관신청) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (대관신청) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(대관신청)</strong> ① 대관을 신청하는 자(이하 ‘신청인’이라 한다)는 희망하는 사용일 이전에 소정양식의 대관신청서를 재단에 제출하여 승인을 얻어야 한다.<br> ② 각각의 창작공간별 대관 대상 기간, 신청의 시기, 방법, 신청양식, 대관자격, 대관조건 등은 대표이사가 별도로 정하여 공고한다.</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (대관승인) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (대관승인) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(대관승인)</strong> ① 재단은 신청인의 대관신청을 접수한 후 대표이사가 별도로 정한 절차에 따라 이를 심사하고, 대관승인 여부를 대관자에게 통보한다.<br> ② 재단은 대관을 승인함에 있어 합리적인 공간운영을 위해 필요하다고 인정될 때에는 조건을 부과하거나 신청인의 의견을 들어 대관기간 및 내용을 조정할 수 있다.<br> ③ 재단은 공정한 대관의 승인 심사를 위해 필요 시 창작공간별로 심의위원회를 구성하여 운영할 수 있다. 이 경우 외부 위촉심의위원들에게 심의비용을 지급할 수 있다.</p><h2 id="article8" class="sr-only" tabindex="-1">제8조 (대관승인 기준) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (대관승인 기준) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(대관승인 기준)</strong> ① 대관승인을 위한 심의기준은 대관 목적의 부합성, 대관일정의 적합 및 수용 가능성, 단체 및 내용 예술성, 과거 이용도 평가 등을 종합하여 대표이사가 별도로 정한다.<br> ② 대관일수 및 일정의 경합 시에는 다음 순서대로 우선 처리한다.</p><ol><li>각 창작공간별 운영 목적에의 부합성</li><li>재단 문화예술지원사업 지원 선정 단체 또는 개인</li><li>정부 또는 지방자치단체에 등록된 전문예술단체 또는 법인</li><li>서울특별시 소재 문화예술 관련 단체 또는 개인</li><li>문화예술 관련 협회 소속 정회원 단체 또는 개인</li></ol><h2 id="article9" class="sr-only" tabindex="-1">제9조 (대관 승인 거부) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (대관 승인 거부) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(대관 승인 거부)</strong> 재단은 다음 각호의 1에 해당하는 사유가 있을 경우에는 대관승인을 거부 할 수 있다.</p><ol><li>법령을 위반하는 내용의 대관을 목적으로 하는 경우</li><li>재단의 시설 및 설비를 심각히 훼손할 우려가 있거나 기타 재단의 관리 유지상 부적절한 연습 및 행사를 목적으로 하는 경우</li><li>다른 대관자의 대관에 심각한 방해가 예상되는 경우 및 기타 재단이 창작공간별로 별도로 정한 신청자격 제한조건에 해당하는 경우</li><li>대관 신청 대상 창작공간 뿐만 아니라 재단이 운영하는 기타 시설 또는 설비에 심대한 피해를 준 사실이 있는 경우</li><li>이 규정에 따른 손해배상의 의무를 성실히 이행하지 않은 경우</li><li>신청인이 성희롱, 성폭력 등의 사유로 기소 중이거나 형 집행 중일 경우 &lt;신설 2018. 3. 23.&gt;</li><li>기타 대관자의 과실 또는 고의로 창작공간 운영목적을 달성하는데 지대한 장애를 초래한 사실이 있는 경우</li></ol><h2 id="article10" class="sr-only" tabindex="-1">제10조 (승인제한 및 취소) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (승인제한 및 취소) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(승인제한 및 취소)</strong> 재단은 다음 각 호의 1에 해당하는 때에는 기 승인된 사항을 제한하거나 취소를 할 수 있다.</p><ol><li>대관승인 후 대관신청서의 기재사실이 허위로 밝혀졌거나, 사용 내용에 중대한 변경 사항이 있을 때</li><li>대관승인 시 지정한 기일 내에 계약을 체결하지 않았을 때</li><li>대관자가 재단의 계약으로 이루어진 창작공간 사용권을 타인에게 양도하거나 전대한 사실이 밝혀졌을 경우</li><li>창작공간별 사용수칙과 대관계약에 위배되는 행위에 대한 재단의 개선 지시를 이행하지 않았을 경우</li><li>신청인이 성희롱, 성폭력 등의 사유로 기소 중이거나 형 집행 중일 경우 &lt;신설 2018. 3. 23.&gt;</li></ol><h2 id="article11" class="sr-only" tabindex="-1">제11조 (대관 계약의 체결) <a class="header-anchor" href="#article11" aria-label="Permalink to &quot;제11조 (대관 계약의 체결) {#article11 .sr-only}&quot;">​</a></h2><p><strong>제11조(대관 계약의 체결)</strong> ① 대관승인을 통보받은 자는 대관승인서에 명시된 일자까지 재단과 계약을 체결해야 한다. 이를 이행하지 않은 경우는 대관의 의사가 없는 것으로 간주하고 대관 승인을 취소할 수 있다.<br> ② 별도 대관계약서를 작성하지 않더라도 대관자의 대관 신청과 재단의 대관 승인통보, 계약금의 납부로 대관계약에 갈음할 수 있다.<br> ③ 대관계약 절차에 관한 세부사항은 창작공간별로 대표이사가 별도로 정한다.</p><h2 id="article12" class="sr-only" tabindex="-1">제12조 (대관계약 취소) <a class="header-anchor" href="#article12" aria-label="Permalink to &quot;제12조 (대관계약 취소) {#article12 .sr-only}&quot;">​</a></h2><p><strong>제12조(대관계약 취소)</strong> ① 대관자는 대관취소신청서를 제출하여 계약된 사용일의 일부 또는 전체를 취소할 수 있다.<br> ② 대관자가 대관취소신청서로 재단에 통보한 경우 다음의 각 호의 경우에만 사용료의 전부 또는 일부를 반환할 수 있다. &lt;개정 2013. 6. 26.&gt;</p><ol><li>천재지변, 기타 불가항력에 의해 대관사용이 불가능하게 된 경우와 사용(시작)일 전일로 부터 최소 15일 이전 대관을 취소한 경우 (100% 반환) &lt;개정 2013. 6. 26.&gt;</li><li>사용(시작)일 전일로부터 최소 7일 이전에 대관취소 신청을 하여 재단의 승인을 얻은 경우(80% 반환) &lt;개정 2013. 6. 26.&gt;</li><li>사용(시작)일 전일부터 6일 이내에 대관취소 신청을 하여 재단의 승인을 얻은 경우(60% 반환) &lt;개정 2013. 6. 26.&gt;</li><li>대관사용 시작일 이후 기사용일을 제외한 잔여 대관기간에 대해 대관 취소를 하고자 하는 경우 (남은 일수의 50% 반환) &lt;개정 2013. 6. 26.&gt;</li></ol><h2 id="article13" class="sr-only" tabindex="-1">제13조 (사용내용 변경금지) <a class="header-anchor" href="#article13" aria-label="Permalink to &quot;제13조 (사용내용 변경금지) {#article13 .sr-only}&quot;">​</a></h2><p><strong>제13조(사용내용 변경금지)</strong> 대관자는 계약내용에서 중대한 변경이 있을 경우 계약된 사용일로부터 7일 이전에 재단에 대관변경신청서를 제출하여 사전에 승인을 얻어야 한다. 재단은 변경 내용의 경중을 심의하여 대관 승인을 취소 또는 제한할 수 있다.</p><h2 id="article14" class="sr-only" tabindex="-1">제14조 (시설 및 설비변경 금지) <a class="header-anchor" href="#article14" aria-label="Permalink to &quot;제14조 (시설 및 설비변경 금지) {#article14 .sr-only}&quot;">​</a></h2><p><strong>제14조(시설 및 설비변경 금지)</strong> ① 대관자는 창작공간 내에 현수막, 홍보안내물 및 가설물의 설치 또는 특수한 장비의 반입에 대하여 재단의 사전 승인을 받아야 한다. 승인받지 않은 설치물과 장비는 재단에서 임의로 철거할 수 있다.<br> ② 대관자는 대관 사용 종료 후, 또는 재단의 요청이 있을 경우 즉시 설치물을 철거하여야 하며, 설치 및 철수로 인해 재단의 기존 시설물, 설비에 손상을 가져온 경우는 변상하여야 한다.<br> ③ 재단은 대관자가 반입한 설비의 철수를 지연할 경우 임의 철거할 수 있으며, 철거에 소요되는 비용은 대관자가 부담한다. 또한 이때 발생한 설비의 손상에 대하여 재단은 책임을 지지 않는다.<br> ④ 재단은 위 ②호 및 ③호의 목적달성을 위해 필요한 경우 사전에 대관자로 하여금 예치금을 납부하게 할 수 있다.<br> ⑤ 대관자는 창작공간 내에 상업적 목적의 어떠한 설치물도 설치할 수 없다.</p><h2 id="article15" class="sr-only" tabindex="-1">제15조 (사용권 양도 및 전대 금지) <a class="header-anchor" href="#article15" aria-label="Permalink to &quot;제15조 (사용권 양도 및 전대 금지) {#article15 .sr-only}&quot;">​</a></h2><p><strong>제15조(사용권 양도 및 전대 금지)</strong> 대관자는 대관사용권을 타인에게 양도 또는 전대하지 못한다. 단, 대관자의 사정에 의해 대관승인 또는 계약체결 후 공동주최, 주관, 후원 등 대관사용주체에 대한 변동사항이 발생 시는 재단의 사전 승인을 받아 시행할 수 있다.</p><h2 id="article16" class="sr-only" tabindex="-1">제16조 (관리 의무 및 손해배상) <a class="header-anchor" href="#article16" aria-label="Permalink to &quot;제16조 (관리 의무 및 손해배상) {#article16 .sr-only}&quot;">​</a></h2><p><strong>제16조(관리 의무 및 손해배상)</strong> ① 대관자는 대관 시설과 설비에 관하여 선량한 사용자로서의 주의 의무를 다해야 하며, 특히 화재 예방에 최선을 다해야 한다.<br> ② 대관자가 전항의 관리의무를 소홀히 하여 시설 및 설비에 대하여 손해를 발생시켰을 경우에는 지체 없이 그 손해액을 배상해야 한다.<br> ③ 대관자는 재단이 정하는 창작공간별 이용 수칙을 준수해야 하며 이를 준수하지 않은 결과로 야기된 안전사고에 대한 민ㆍ형사상 책임을 진다.<br> ④ 재단은 대관기간 중(준비 및 마무리기간 포함)재단에서 고의 또는 중과실이 있는 경우를 제외하고는 어떠한 인적, 물적 손해에 대하여서도 손해배상 책임을 지지 않는다.<br> ⑤ 관할 자치구 폐기물관리 조례에 의거, 폐기물 수수료가 종량제로 시행됨에 따라 연습준비, 연습, 철수기간 중 발생하는 쓰레기 폐기를 위한 수수료를 실비로 대관자에게 부과할 수 있다.</p><h2 id="article17" class="sr-only" tabindex="-1">제17조 (규정의 효력) <a class="header-anchor" href="#article17" aria-label="Permalink to &quot;제17조 (규정의 효력) {#article17 .sr-only}&quot;">​</a></h2><p><strong>제17조(규정의 효력)</strong> 본 규정은 재단과 대관자간의 계약의 일부로 간주되며 계약서와 동일한 효력을 지닌다.</p><h2 id="article18" class="sr-only" tabindex="-1">제18조 (항변권) <a class="header-anchor" href="#article18" aria-label="Permalink to &quot;제18조 (항변권) {#article18 .sr-only}&quot;">​</a></h2><p><strong>제18조(항변권)</strong> ① 재단의 귀책사유로 인하여 계약을 체결할 수 없거나 대관을 진행할 수 없는 등의 경우에 대관자는 항변할 수 있다.<br> ② 항변에 따른 사유가 객관적으로 인정되는 경우 재단은 그에 따른 배상 및 그에 상응하는 조치를 취해야 한다.</p><h2 id="article19" class="sr-only" tabindex="-1">제19조 (규정변경 승인) <a class="header-anchor" href="#article19" aria-label="Permalink to &quot;제19조 (규정변경 승인) {#article19 .sr-only}&quot;">​</a></h2><p><strong>제19조(규정변경 승인)</strong> 이 규정을 변경할 경우 재단은 홈페이지 및 안내문을 통하여 대관자에게 공지하는 것을 변경된 규약의 승인으로 간주한다.</p><h2 id="article20" class="sr-only" tabindex="-1">제20조 (이 규정에 정하지 않은 사항) <a class="header-anchor" href="#article20" aria-label="Permalink to &quot;제20조 (이 규정에 정하지 않은 사항) {#article20 .sr-only}&quot;">​</a></h2><p><strong>제20조(이 규정에 정하지 않은 사항)</strong> 이 규정에 정하지 않은 사항과 규정의 해석에 관하여는 재단의 관련 규정과 관계법령 또는 관례에 따른다.</p><h2 id="article21" class="sr-only" tabindex="-1">제21조 (관할법원) <a class="header-anchor" href="#article21" aria-label="Permalink to &quot;제21조 (관할법원) {#article21 .sr-only}&quot;">​</a></h2><p><strong>제21조(관할법원)</strong> 이 규정에 따른 분쟁이 발생할 경우, 관할법원은 서울지방법원으로 한다.</p><h2 id="article22" class="sr-only" tabindex="-1">제22조 (규정위반시의 책임) <a class="header-anchor" href="#article22" aria-label="Permalink to &quot;제22조 (규정위반시의 책임) {#article22 .sr-only}&quot;">​</a></h2><p><strong>제22조(규정위반시의 책임)</strong> 이 규정을 위반함으로써 발생하는 모든 책임은 대관자가 부담하며, 이로 인하여 상대방에게 손해를 입힐 경우에는 이를 배상해야 한다.</p><h2 id="article23" class="sr-only" tabindex="-1">제23조 (시행내규) <a class="header-anchor" href="#article23" aria-label="Permalink to &quot;제23조 (시행내규) {#article23 .sr-only}&quot;">​</a></h2><p><strong>제23조(시행내규)</strong> 이 규정의 시행과 관련한 세부 필요사항은 내규로 정한다.</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong><br> 제1조(적용시기) 본 규정은 이사회의 승인을 얻은 날로부터 시행한다.</p><h2 id="addendum2" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum2" aria-label="Permalink to &quot;부칙 {#addendum2 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2009. 9. 8.&gt;<br> 제1조(적용시기) 본 규정은 2009년 9월 8일부터 시행한다.</p><h2 id="addendum3" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum3" aria-label="Permalink to &quot;부칙 {#addendum3 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2010. 3. 30.&gt;<br> 제1조(적용시기) 본 규정은 2010년 3월 30일부터 시행한다.</p><h2 id="addendum4" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum4" aria-label="Permalink to &quot;부칙 {#addendum4 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2010. 10. 26.&gt;<br> 제1조(적용시기) 본 규정은 2010년 10월 26일부터 시행한다.</p><h2 id="addendum5" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum5" aria-label="Permalink to &quot;부칙 {#addendum5 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2011. 3. 30.&gt;<br> 제1조(적용시기) 본 규정은 2011년 3월 30일부터 시행한다.</p><h2 id="addendum6" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum6" aria-label="Permalink to &quot;부칙 {#addendum6 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2013. 6. 26.&gt;<br> 제1조(적용시기) 본 규정은 2013년 6월 26일부터 시행한다.</p><h2 id="addendum7" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum7" aria-label="Permalink to &quot;부칙 {#addendum7 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2018. 3. 23.&gt;<br> 제1조(적용시기) 본 규정은 2018년 3월 23일부터 시행한다.<br><strong>[별표 1]</strong> &lt;개정 2009. 9. 8., 2010. 3. 30.&gt; <strong>, 삭제 &lt;2010. 10. 26.&gt;</strong></p><p><strong>[별표 2]</strong> &lt;개정 2009. 9. 8., 2010. 3. 30.&gt; <strong>, 삭제 &lt;2010. 10. 26.&gt;</strong></p>`,67)]))}const u=r(o,[["render",s]]);export{b as __pageData,u as default};
